import{_ as d,C as n,o as l,c as h,ag as r,E as i,j as t,a as o}from"./chunks/framework.DMVuHR7L.js";const y=JSON.parse('{"title":"Connecting a device","description":"","frontmatter":{},"headers":[],"relativePath":"features/connecting.md","filePath":"features/connecting.md","lastUpdated":1779649727000}'),c={name:"features/connecting.md"},p={id:"device-proxy",tabindex:"-1"};function u(g,e,m,b,f,v){const a=n("ThemeImage"),s=n("Badge");return l(),h("div",null,[e[5]||(e[5]=r('<h1 id="connecting-a-device" tabindex="-1">Connecting a device <a class="header-anchor" href="#connecting-a-device" aria-label="Permalink to &quot;Connecting a device&quot;">​</a></h1><p>WebLogcat talks to the phone directly from the browser via <strong>WebUSB</strong>. There is no <code>adb</code> install on the laptop, no Android Studio, no proxy server — permission is granted through Chromium&#39;s standard device chooser and the on-device authorisation prompt.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>Chromium-based browser</strong>: Chrome, Edge, Brave, Opera, Arc. Firefox and Safari don&#39;t ship WebUSB, so the <strong>Connect a device</strong> button is disabled there.</li><li>The site served over <strong>HTTPS</strong> or from <code>localhost</code>. The hosted versions at <code>https://gabrielhuff.github.io/web-logcat/</code> (production) and <code>https://gabrielhuff.github.io/web-logcat/staging/</code> (staging) qualify; so does <code>npm run dev</code>.</li><li>An <strong>Android device</strong> with USB debugging enabled in <em>Settings → System → Developer options</em>.</li></ul><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2>',5)),i(a,{"src-dark":"/img/features/empty-state.png","src-light":"/img/features/empty-state-light.png",alt:"Connecting flow"}),e[6]||(e[6]=r('<ol><li>Plug the device in with a data-capable USB cable.</li><li>Click <strong>Connect a device</strong>. The browser shows its device chooser; pick your phone.</li><li>The phone shows the standard <em>Allow USB debugging?</em> prompt the first time. Tick <strong>Always allow from this computer</strong> if you want subsequent connects to be silent.</li><li>The dashboard mounts with a single Logcat tile filling the viewport. The topbar shows the device model and serial; the connection dot is green for real devices and amber for the simulator. Use <strong>+ Add widget</strong> to add more tiles.</li></ol><p>The browser remembers the WebUSB grant the same way it remembers any other permission — the second connect from the same browser+device pair is silent.</p><h2 id="switching-devices" tabindex="-1">Switching devices <a class="header-anchor" href="#switching-devices" aria-label="Permalink to &quot;Switching devices&quot;">​</a></h2><p>The device pill in the topbar opens a picker showing every device the browser has paired in this session, plus the simulator if it&#39;s been used. Pick a row to switch; the previous stream stays warm in the background so you can flip back without re-authorising.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause / fix</th></tr></thead><tbody><tr><td>Chooser is empty</td><td>Verify USB debugging is on, the device is unlocked, and the cable is data-capable. Replug and reload.</td></tr><tr><td>Pairing prompt never appears on the phone</td><td>Some OEMs hide it behind a notification. Pull down the shade.</td></tr><tr><td><code>Connect a device</code> is disabled</td><td>You&#39;re on Firefox / Safari, or the page isn&#39;t served from HTTPS / localhost.</td></tr><tr><td>Connection drops on screen-off</td><td>Some manufacturers cut USB after sleep. Disable screen-locked-off behaviour or keep the screen awake.</td></tr><tr><td>Mirror shows &quot;device not supported&quot;</td><td>Mirror needs <code>scrcpy</code> v2.7 capabilities. Older / very locked-down devices may refuse the push.</td></tr></tbody></table><p>If the chooser shows the phone but the connect step fails, check the browser console — the toast message comes from <code>friendlyConnectError()</code> in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/adb.ts" target="_blank" rel="noreferrer"><code>lib/adb.ts</code></a> and the underlying error usually points at the cause (timeout, permission denied, USB endpoint busy).</p><h2 id="don-t-have-a-phone" tabindex="-1">Don&#39;t have a phone? <a class="header-anchor" href="#don-t-have-a-phone" aria-label="Permalink to &quot;Don&#39;t have a phone?&quot;">​</a></h2><p>Click <strong>fake data</strong> on the empty state. The dashboard runs against the <a href="./simulator">simulated stream</a> so every widget renders against in-memory fixtures.</p>',9)),t("h2",p,[e[0]||(e[0]=o("Device Proxy ",-1)),i(s,{type:"warning",text:"experimental"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#device-proxy","aria-label":'Permalink to "Device Proxy <Badge type="warning" text="experimental" />"'},"​",-1))]),e[7]||(e[7]=r('<p>WebUSB has limits: it can&#39;t reach <strong>emulators</strong> or <strong>Wi-Fi-attached</strong> devices, it requires <strong>exclusive USB access</strong> (Android Studio / scrcpy / <code>adb shell</code> can&#39;t run alongside), and it isn&#39;t in <strong>Firefox</strong> or <strong>Safari</strong>. The Device Proxy transport fixes all four — at the cost of a small one-time daemon install.</p><div class="warning custom-block"><p class="custom-block-title">macOS support</p><p>Google doesn&#39;t currently ship a macOS build of the daemon, so the Device Proxy can&#39;t be set up on macOS today. Tracking at <a href="https://github.com/gabrielhuff/web-logcat/issues/133" target="_blank" rel="noreferrer">#133</a>.</p></div><p>The dropdown arrow next to <strong>Connect a device</strong> lets you pick a transport explicitly:</p>',3)),i(a,{"src-dark":"/img/features/connect-dropdown.png","src-light":"/img/features/connect-dropdown-light.png",alt:"Connect-a-device button with a dropdown arrow, opened to show 'Connect via WebUSB' and 'Connect via Web Device Proxy' (experimental) options"}),e[8]||(e[8]=t("p",null,[o("The primary button follows whichever is "),t("strong",null,"available"),o(" in your environment — if the proxy daemon is running on "),t("code",null,"localhost:9167"),o(", the primary defaults to proxy; otherwise it falls back to WebUSB.")],-1)),e[9]||(e[9]=t("h3",{id:"connect-via-the-proxy",tabindex:"-1"},[o("Connect via the proxy "),t("a",{class:"header-anchor",href:"#connect-via-the-proxy","aria-label":'Permalink to "Connect via the proxy"'},"​")],-1)),t("ol",null,[t("li",null,[e[3]||(e[3]=t("p",null,[t("strong",null,"Install the daemon."),o(" Pick "),t("strong",null,"Connect via Web Device Proxy"),o(" from the dropdown. If the daemon isn't running, the dialog shows an "),t("strong",null,"Install"),o(" button that opens the official Google download page in a new tab. Run the installer and re-open the dialog.")],-1)),i(a,{"src-dark":"/img/features/wdp-dialog.png","src-light":"/img/features/wdp-dialog-light.png",alt:"Web Device Proxy dialog showing 'Daemon not detected' with an Install button"})]),e[4]||(e[4]=r("<li><p><strong>Authorize WebLogcat.</strong> The first time the proxy sees this origin it serves a small Google-hosted approval page in a popup. Click <em>Allow</em> — subsequent visits from this origin are silent.</p></li><li><p><strong>Pick a device.</strong> The dialog lists everything <code>adb devices</code> shows: USB phones, emulators, Wi-Fi attachments. Click <strong>Connect</strong> on the row you want. If a device shows <strong>PROXY_UNAUTHORIZED</strong>, click <strong>Authorize</strong> instead — that triggers a per-device approval popup and re-tries the connect once the device transitions to ready.</p></li>",2))]),e[10]||(e[10]=r('<p>After connect, the dashboard mounts and behaves exactly the same as under WebUSB — every tile (Logcat, Shell, Dumpsys, Files, Mirror) works without modification.</p><h3 id="when-to-use-which" tabindex="-1">When to use which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to &quot;When to use which&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Need</th><th>WebUSB</th><th>Device Proxy</th></tr></thead><tbody><tr><td>Zero install</td><td>✅</td><td>Requires the daemon</td></tr><tr><td>Multiple devices visible at once</td><td>❌ (one chooser pick)</td><td>✅</td></tr><tr><td>Coexist with Android Studio / scrcpy / <code>adb</code></td><td>❌ (exclusive claim)</td><td>✅</td></tr><tr><td>Emulators</td><td>❌</td><td>✅</td></tr><tr><td>Wi-Fi-attached devices (<code>adb connect</code>)</td><td>❌</td><td>✅</td></tr><tr><td>Firefox / Safari</td><td>❌</td><td>✅ (any browser)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Note</p><p>If the proxy daemon is running, <code>adb-server</code> already holds the USB claim — meaning WebUSB will fail with <em>&quot;device already in use&quot;</em> until you stop the daemon (or kill <code>adb-server</code>). That&#39;s why the primary button defaults to the proxy whenever it&#39;s detected.</p></div><h3 id="troubleshooting-1" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting-1" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause / fix</th></tr></thead><tbody><tr><td>&quot;Daemon not detected&quot;</td><td>Proxy isn&#39;t running on <code>localhost:9167</code>. Install or restart it.</td></tr><tr><td>&quot;Browser blocked the approve popup&quot;</td><td>Allow popups for this origin, then retry. The popup is a one-time Google-hosted approval page.</td></tr><tr><td>Device shows <code>OFFLINE</code> / <code>UNAUTHORIZED</code></td><td>Accept the on-device debugging prompt and re-open the dialog.</td></tr><tr><td>WebUSB suddenly fails with &quot;device in use&quot;</td><td>The proxy daemon claimed it via <code>adb</code>. Quit the daemon or pick <strong>Connect via Web Device Proxy</strong> from the dropdown.</td></tr></tbody></table>',6))])}const T=d(c,[["render",u]]);export{y as __pageData,T as default};
